import heapq

def pop_in_order(nums):
    heap = []                              # heapq works on a plain list
    for x in nums:
        heapq.heappush(heap, x)            # O(log n) each
    out = []
    while heap:
        out.append(heapq.heappop(heap))    # smallest first
    return out

List<Integer> popInOrder(int[] nums) {
    PriorityQueue<Integer> heap = new PriorityQueue<>();   // a min-heap
    for (int x : nums) heap.offer(x);                      // O(log n) each
    List<Integer> out = new ArrayList<>();
    while (!heap.isEmpty()) out.add(heap.poll());          // smallest first
    return out;
}

vector<int> popInOrder(const vector<int>& nums) {
    priority_queue<int, vector<int>, greater<int>> heap;   // greater<int>: a min-heap
    for (int x : nums) heap.push(x);                       // O(log n) each
    vector<int> out;
    while (!heap.empty()) {
        out.push_back(heap.top());                         // smallest first...
        heap.pop();                                        // ...then remove it
    }
    return out;
}

class Heap {
  constructor(compare = (a, b) => a - b) {   // a - b: min-heap,  b - a: max-heap
    this.items = [];
    this.compare = compare;                   // negative when a should come out before b
  }
  static from(values, compare) {              // heapify a whole array in O(n)
    const heap = new Heap(compare);
    heap.items = [...values];
    for (let i = Math.floor(values.length / 2) - 1; i >= 0; i--) heap.siftDown(i);
    return heap;
  }
  size() {
    return this.items.length;
  }
  peek() {
    return this.items[0];                     // the top; undefined when empty
  }
  push(x) {
    this.items.push(x);                       // add at the end...
    this.siftUp(this.items.length - 1);       // ...and let it rise
  }
  pop() {
    const a = this.items;
    if (a.length === 0) return undefined;
    const top = a[0];
    const last = a.pop();
    if (a.length > 0) {
      a[0] = last;                            // move the last item to the top...
      this.siftDown(0);                       // ...and let it sink
    }
    return top;
  }
  siftUp(i) {
    const a = this.items;
    while (i > 0) {
      const parent = Math.floor((i - 1) / 2);
      if (this.compare(a[parent], a[i]) <= 0) break;   // parent comes first: done
      [a[parent], a[i]] = [a[i], a[parent]];
      i = parent;
    }
  }
  siftDown(i) {
    const a = this.items;
    while (true) {
      const left = 2 * i + 1, right = left + 1;
      let first = i;
      if (left < a.length && this.compare(a[left], a[first]) < 0) first = left;
      if (right < a.length && this.compare(a[right], a[first]) < 0) first = right;
      if (first === i) return;                // both children come later: done
      [a[i], a[first]] = [a[first], a[i]];
      i = first;
    }
  }
}

function treatmentOrder(severity) {
  // [severity, arrival]: higher severity first; on a tie, whoever arrived first
  const heap = new Heap((a, b) => b[0] - a[0] || a[1] - b[1]);
  severity.forEach((s, i) => heap.push([s, i]));
  const order = [];
  while (heap.size() > 0) order.push(heap.pop()[1]);   // arrival numbers, in treatment order
  return order;
}

import heapq

def treatment_order(severity):
    # (-severity, arrival): heapq is a min-heap, so negate to put the most severe first;
    # on a tie the tuples compare arrival next, so whoever came first wins
    heap = []
    for i, s in enumerate(severity):
        heapq.heappush(heap, (-s, i))
    order = []
    while heap:
        order.append(heapq.heappop(heap)[1])   # arrival numbers, in treatment order
    return order

List<Integer> treatmentOrder(int[] severity) {
    // {severity, arrival}: higher severity first; on a tie, whoever arrived first
    PriorityQueue<int[]> heap = new PriorityQueue<>(
        (a, b) -> a[0] != b[0] ? Integer.compare(b[0], a[0]) : Integer.compare(a[1], b[1]));
    for (int i = 0; i < severity.length; i++) heap.offer(new int[]{severity[i], i});
    List<Integer> order = new ArrayList<>();
    while (!heap.isEmpty()) order.add(heap.poll()[1]);    // arrival numbers, in treatment order
    return order;
}

vector<int> treatmentOrder(const vector<int>& severity) {
    // pair(severity, -arrival): the default max-heap puts the highest severity on top,
    // and on a tie the larger -arrival, which is whoever arrived first
    priority_queue<pair<int, int>> heap;
    for (int i = 0; i < (int)severity.size(); i++) heap.push({severity[i], -i});
    vector<int> order;
    while (!heap.empty()) {
        order.push_back(-heap.top().second);           // arrival numbers, in treatment order
        heap.pop();
    }
    return order;
}
